class CompleteCafeListScreen extends StatefulWidget {
  static const String routeName = '/CompleteCafeListScreen';

  const CompleteCafeListScreen({super.key});

  @override
  State<CompleteCafeListScreen> createState() => _BookingsScreenState();
}

class _BookingsScreenState extends State<CompleteCafeListScreen> {
  static _BookingsScreenState? of(BuildContext context) =>
      context.findAncestorStateOfType<_BookingsScreenState>();

  @override
  void initState() {
    super.initState();
    context.read<BookingBloc>().add(GetBookingsEvent());
    context.read<BookingBloc>().add(FilterBookingsByTabEvent(0)); // Reset to CHECKIN tab
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      extendBodyBehindAppBar: true,
      appBar: AppBar(
        title: Text(
          'COMPLETED BOOKINGS',
          style: TextStyle(
            color: GlassTheme.textColor(context),
            fontWeight: FontWeight.w900,
            fontSize: 15,
            letterSpacing: 1.5,
          ),
        ),
        centerTitle: true,
        leading: Padding(
          padding: const EdgeInsets.all(8.0),
          child: _GlassHeaderButton(
            icon: Icons.arrow_back_ios_new_rounded,
            onTap: () => Navigator.pop(context),
          ),
        ),
        elevation: 0,
        backgroundColor: Colors.transparent,
      ),
      body: ZinkoBackground(
        child: MultiBlocListener(
          listeners: [
            BlocListener<BookingBloc, BookingState>(
              listener: (context, state) {
                if (state is BookingError) {
                  Flushbar(
                    title: "Error",
                    message: state.message,
                    duration: const Duration(seconds: 4),
                    flushbarPosition: FlushbarPosition.TOP,
                    backgroundColor: Colors.redAccent.withValues(alpha: 0.9),
                    icon: const Icon(Icons.error_outline, color: Colors.white),
                    borderRadius: BorderRadius.circular(12),
                    margin: const EdgeInsets.all(12),
                  ).show(context);
                } else if (state is BookingOperationSuccess) {
                  Flushbar(
                    title: "Success",
                    message: state.message,
                    duration: const Duration(seconds: 4),
                    flushbarPosition: FlushbarPosition.TOP,
                    backgroundColor: Colors.green.withValues(alpha: 0.9),
                    icon: const Icon(Icons.check_circle_outline, color: Colors.white),
                    borderRadius: BorderRadius.circular(12),
                    margin: const EdgeInsets.all(12),
                  ).show(context);
                }
              },
            ),
            BlocListener<FeedbackBloc, FeedbackState>(
              listener: (context, state) {
                if (state is FeedbackError) {
                  Flushbar(
                    title: "Error",
                    message: state.message,
                    duration: const Duration(seconds: 4),
                    flushbarPosition: FlushbarPosition.TOP,
                    backgroundColor: Colors.redAccent.withValues(alpha: 0.9),
                    icon: const Icon(Icons.error_outline, color: Colors.white),
                    borderRadius: BorderRadius.circular(12),
                    margin: const EdgeInsets.all(12),
                  ).show(context);
                } else if (state is FeedbackSuccess) {
                  Flushbar(
                    title: "Success",
                    message: state.message,
                    duration: const Duration(seconds: 4),
                    flushbarPosition: FlushbarPosition.TOP,
                    backgroundColor: Colors.green.withValues(alpha: 0.9),
                    icon: const Icon(Icons.check_circle_outline, color: Colors.white),
                    borderRadius: BorderRadius.circular(12),
                    margin: const EdgeInsets.all(12),
                  ).show(context);
                }
              },
            ),
          ],
          child: SafeArea(
            child: BlocBuilder<BookingBloc, BookingState>(
              builder: (context, state) {
                if (state is BookingLoading) {
                  return Center(child: CircularProgressIndicator(color: GlassTheme.textColor(context)));
                } else if (state is BookingsLoaded) {
                  final filteredBookings = state.bookings.where((b) {
                    final status = b.bookingStatus.toUpperCase();
                    if (state.tabIndex == 0) return status == 'CHECKIN';
                    if (state.tabIndex == 1) return status == 'COMPLETED';
                    return false;
                  }).toList();

                  return Column(
                    children: [
                      const SizedBox(height: 8),
                      _buildTabs(context, state.tabIndex),
                      Expanded(
                        child: RefreshIndicator(
                          onRefresh: () async {
                            context.read<BookingBloc>().add(GetBookingsEvent());
                          },
                          color: GlassTheme.textColor(context),
                          child: filteredBookings.isEmpty
                              ? _buildEmptyState(context)
                              : ListView.builder(
                                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 100),
                                  physics: const AlwaysScrollableScrollPhysics(parent: BouncingScrollPhysics()),
                                  itemCount: filteredBookings.length,
                                  itemBuilder: (context, index) {
                                    return _BookingCard(
                                      booking: filteredBookings[index],
                                    ).animate().fadeIn(delay: (index * 80).ms);
                                  },
                                ),
                        ),
                      ),
                    ],
                  );
                }
                return const SizedBox.shrink();
              },
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildEmptyState(BuildContext context) {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            padding: const EdgeInsets.all(24),
            decoration: BoxDecoration(
              color: GlassTheme.glassColor(context),
              shape: BoxShape.circle,
              border: Border.all(color: GlassTheme.glassBorder(context)),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.2),
                  blurRadius: 30,
                  offset: const Offset(0, 10),
                )
              ],
            ),
            child: Icon(
              Icons.event_busy_rounded,
              size: 40,
              color: GlassTheme.textColor(context).withValues(alpha: 0.4),
            ),
          ).animate().scale(duration: 600.ms, curve: Curves.easeOutBack),
          const SizedBox(height: 24),
          Text(
            'NO BOOKINGS',
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.w900,
              color: GlassTheme.textColor(context),
              letterSpacing: -0.5,
            ),
          ).animate().fadeIn(delay: 200.ms),
          const SizedBox(height: 8),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 48),
            child: Text(
              'Your future reservations will appear here. Start exploring workspaces now.',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                color: GlassTheme.secondaryTextColor(context),
                height: 1.5,
              ),
            ),
          ).animate().fadeIn(delay: 400.ms),
        ],
      ),
    );
  }
}

  Widget _buildTabs(BuildContext context, int selectedTab) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 8),
      child: ZinkoCommonCard(
        padding: const EdgeInsets.all(4),
        child: Row(
          children: [
            _TabItem(
                title: 'CHECKIN',
                isSelected: selectedTab == 0,
                onTap: () => context.read<BookingBloc>().add(FilterBookingsByTabEvent(0))),
            _TabItem(
                title: 'COMPLETED',
                isSelected: selectedTab == 1,
                onTap: () => context.read<BookingBloc>().add(FilterBookingsByTabEvent(1))),
          ],
        ),
      ),
    );
  }

