                    padding: const EdgeInsets.all(24),
                    decoration: BoxDecoration(
                      color: const Color(0xFF1A1A1A).withValues(alpha: 0.9),
                      borderRadius: BorderRadius.circular(24),
                      border: Border.all(color: Colors.white.withValues(alpha: 0.1)),
                    ),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Center(
                          child: Text(
                            'BOOKING DETAILS',
                            style: TextStyle(
                              color: GlassTheme.textColor(context),
                              fontWeight: FontWeight.w900,
                              fontSize: 18,
                              letterSpacing: 1,
                            ),
                          ),
                        ),
                        const SizedBox(height: 24),
                        _DetailItem(label: 'CAFE', value: booking.cafeName, icon: Icons.store_rounded),
                        _DetailItem(label: 'ADDRESS', value: booking.address, icon: Icons.location_on_rounded),
                        _DetailItem(label: 'TIME SLOT', value: booking.timeSlot, icon: Icons.access_time_filled_rounded),
                        _DetailItem(label: 'SEAT TYPE', value: booking.seatType, icon: Icons.chair_rounded),
                        _DetailItem(
                          label: 'PERSONS',
                          value: '${booking.noOfPersons} Persons',
                          icon: Icons.people_alt_rounded,
                        ),
                        _DetailItem(
                          label: 'TOTAL AMOUNT',
                          value: '₹${booking.totalAmount}',
                          icon: Icons.payments_rounded,
                          valueColor: Colors.greenAccent,
                        ),
                        const SizedBox(height: 12),
                        Container(
                          padding: const EdgeInsets.all(12),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.05),
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Text('CODE',
                                  style: TextStyle(
                                      color: GlassTheme.textColor(context).withValues(alpha: 0.5),
                                      fontSize: 10,
                                      fontWeight: FontWeight.w900)),
                              Text(booking.bookingCode,
                                  style: TextStyle(
                                      color: GlassTheme.textColor(context), fontSize: 12, fontWeight: FontWeight.w900)),
                            ],
                          ),
                        ),
                        const SizedBox(height: 24),
                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton(
                            onPressed: () => Navigator.pop(context),
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.white,
                              foregroundColor: Colors.black,
                              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                            ),
                            child: const Text('CLOSE', style: TextStyle(fontWeight: FontWeight.w900)),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

